// TK-009 gate: на 60 местах sample60 (TK-008) подпись района по координатам вместо area модели.
// Берёт кэш Nominatim reverse zoom=14 (raw60.json, новых запросов нет), прогоняет боевую pickArea
// и считает долю A по правилу PROTOCOL.md §2.1 (подпись ↔ районы точки).
// Запуск: node tools/tk009_gate60.mjs   (итог: C:/verger-data/pilot/tk008/gate_tk009.json)
import { readFileSync, writeFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import { runInNewContext } from 'node:vm';

const D8 = 'C:/verger-data/pilot/tk008/';
const ts = createRequire(import.meta.url)('../app/node_modules/typescript');
const exports = {};
const src = readFileSync(new URL('../app/imports/api/places/areaFromCoords.ts', import.meta.url), 'utf8');
runInNewContext(ts.transpileModule(src, { compilerOptions: { module: ts.ModuleKind.CommonJS, target: ts.ScriptTarget.ES2022 } }).outputText,
  { exports, console, AbortSignal, Number, Map, Promise, setTimeout, Date });
const { pickArea } = exports;

const NOISE = new Set(['district', 'quarter', 'arrondissement', 'ward', 'borough', 'neighborhood', 'neighbourhood', 'area', 'the', 'de', 'di', 'la', 'le', 'el', 'of', 'del', 'des', 'du']);
const norm = s => s.toLowerCase().normalize('NFKD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9 ]/g, ' ').split(/\s+/).filter(Boolean);
const sig = s => new Set(norm(s).filter(w => !NOISE.has(w)));
const subset = (a, b) => [...a].every(x => b.has(x));
// правило 2.1: все значимые слова подписи входят в одно из полей точки или поле целиком входит в подпись
const matches = (label, names) => { const sa = sig(label); return sa.size > 0 && names.some(n => { const sn = sig(n); return subset(sa, sn) || (sn.size > 0 && subset(sn, sa)); }); };

const raw = JSON.parse(readFileSync(D8 + 'raw60.json', 'utf8'));
const rows = JSON.parse(readFileSync(D8 + 'area60_final.json', 'utf8'));
const out = rows.map(r => {
  const address = raw[`rv14|${r.i}`]?.address;
  const city = address?.city ?? address?.town ?? address?.village;
  const label = pickArea(address, city);
  const wasWrong = !r.match_names && !r.match_label_geocode;           // подпись модели не соответствует точке (§2.1/§2.2)
  const nowShown = label !== '';
  const nowMismatch = nowShown && !matches(label, r.point_districts);   // подпись по координатам не соответствует точке
  return { i: r.i, name: r.name, was: r.area_shown, was_class: r.class, was_wrong: wasWrong, now: label, hidden: !nowShown, now_mismatch: nowMismatch,
           now_A: nowMismatch && r.real_place_osm && r.real_place_osm.dist_m <= 300 };
});
const n = out.length;
const res = {
  n,
  before: { class_A: rows.filter(r => r.class === 'A').length, A_plus_AB: rows.filter(r => r.class === 'A' || r.class === 'A/B?').length, label_not_matching_point: out.filter(o => o.was_wrong).length },
  after: { class_A: out.filter(o => o.now_A).length, label_not_matching_point: out.filter(o => o.now_mismatch).length, hidden_no_data: out.filter(o => o.hidden).length, shown: out.filter(o => !o.hidden).length },

